create or replace function private.aios_task_status_guard() returns trigger language plpgsql security definer set search_path='' as $$ begin if tg_op='UPDATE' and new.status is distinct from old.status then if not((old.status='queued' and new.status in('assigned','ready','running','cancelled','expired')) or(old.status='assigned' and new.status in('ready','running','cancelled','expired')) or(old.status='ready' and new.status in('running','cancelled','expired')) or(old.status='running' and new.status in('blocked_pending_approval','completed','failed','cancelled','expired')) or(old.status='blocked_pending_approval' and new.status in('approved','failed','cancelled','expired')) or(old.status='approved' and new.status in('running','cancelled','expired'))) then raise exception 'invalid task state transition: % -> %',old.status,new.status; end if; end if; if new.status='completed' and not exists(select 1 from public.aios_tool_invocations i where i.task_id=new.id and i.organization_id=new.organization_id and i.status='succeeded') then raise exception 'task cannot complete without a succeeded tool invocation'; end if; if new.status='running' and new.started_at is null then new.started_at=now(); end if; if new.status in('completed','failed','cancelled','expired') and new.completed_at is null then new.completed_at=now(); end if; return new; end; $$;
create or replace function private.aios_mission_status_guard() returns trigger language plpgsql security definer set search_path='' as $$ begin if tg_op='UPDATE' and new.status is distinct from old.status then if not((old.status='queued' and new.status in('running','cancelled','expired')) or(old.status='running' and new.status in('blocked_pending_approval','completed','failed','cancelled','expired')) or(old.status='blocked_pending_approval' and new.status in('running','completed','failed','cancelled','expired'))) then raise exception 'invalid mission state transition: % -> %',old.status,new.status; end if; end if; if new.status='completed' and exists(select 1 from public.aios_tasks t where t.mission_id=new.id and t.status<>'completed') then raise exception 'mission cannot complete while tasks remain incomplete'; end if; if new.status='running' and new.started_at is null then new.started_at=now(); end if; if new.status in('completed','failed','cancelled','expired') and new.completed_at is null then new.completed_at=now(); end if; return new; end; $$;
